#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill. Re-runnable: saved values are offered as defaults.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Google Cloud project and Microsoft app registration for Cloud
# Backing (docs/adr/0011). Writes the public client IDs and redirect schemes
# to apple/Config/CloudClients.xcconfig, which the Apple app reads via
# Info.plist (see apple/project.yml).
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

BUNDLE_ID="com.timhilt.leafpdf"
CLIENTS_FILE="apple/Config/CloudClients.xcconfig"
GOOGLE_ID_RE='^[0-9]+-[a-z0-9]+\.apps\.googleusercontent\.com$'
MICROSOFT_ID_RE='^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
MS_APPS="https://entra.microsoft.com/#view/Microsoft_AAD_RegisteredApps/ApplicationsListBlade/quickStartType~/null/sourceType/Microsoft_AAD_IAM"

# ask_valid KEY "Prompt" REGEX "Error" re-asks until the answer matches.
ask_valid() {
  while :; do
    ask "$1" "$2"
    [[ "${!1}" =~ $3 ]] && return 0
    warn "$4"
  done
}

# write_clients regenerates the committed xcconfig from the four values.
write_clients() {
  cat > "$CLIENTS_FILE" <<CONFIG
// Public OAuth client IDs and redirect URL schemes for Cloud Backing. Not
// secrets. Generated by scripts/cloud-oauth-wizard.sh: re-run it, don't edit.
GOOGLE_CLIENT_ID = ${GOOGLE_CLIENT_ID:-}
GOOGLE_REDIRECT_SCHEME = ${GOOGLE_REDIRECT_SCHEME:-}
MICROSOFT_CLIENT_ID = ${MICROSOFT_CLIENT_ID:-}
MICROSOFT_REDIRECT_SCHEME = ${MICROSOFT_REDIRECT_SCHEME:-}
CONFIG
  printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$CLIENTS_FILE"
}

cd "$(git rev-parse --show-toplevel)"

# Seed the prompts' defaults from the committed xcconfig so re-runs offer the
# saved values. ENV_FILE is a scratch file; the xcconfig is the real output.
ENV_FILE=$(mktemp)
trap 'rm -f "$ENV_FILE"' EXIT
if [[ -f "$CLIENTS_FILE" ]]; then
  while IFS=' =' read -r key value; do
    [[ "$key" =~ ^[A-Z_]+$ && -n "$value" ]] && printf "%s='%s'\n" "$key" "$value" >> "$ENV_FILE"
  done < <(sed -nE 's/^([A-Z_]+) *= *(.*[^ ])$/\1 \2/p' "$CLIENTS_FILE")
fi

banner "LeafPDF: Google Cloud and Microsoft app registrations"

stage "Google: project"
say "One project holds the OAuth clients of every platform (ADR-0011)."
say "Otherwise one platform can't see the LeafPDF folder another created."
open_url "https://console.cloud.google.com/projectcreate"
step "Project name: LeafPDF. Create it (or reuse an existing LeafPDF project)."
step "Make sure that project is selected in the top bar."
pause "Project ready?"

stage "Google: enable the Drive API"
open_url "https://console.cloud.google.com/apis/library/drive.googleapis.com"
step "With the LeafPDF project selected, click Enable."
note "If it says 'Manage' or 'API enabled', it's already on."
pause "Drive API enabled?"

stage "Google: consent screen, only drive.file, In production"
say "In 'Testing', refresh tokens expire after 7 days, so publishing matters."
open_url "https://console.cloud.google.com/auth/branding"
step "Branding: app name LeafPDF, your support and developer emails. Save."
step "Audience: user type External, then 'Publish app' → Confirm."
step "The publishing status must read 'In production'."
step "Data Access → Add or remove scopes → tick only the Drive scope"
say "    https://www.googleapis.com/auth/drive.file"
step "Update, then Save. Keep only that and the default openid/email/profile."
note "drive.file is non-sensitive: no verification or security assessment needed."
note "Console labels move around; the sidebar is Google Auth Platform."
confirm "Status is 'In production' and drive.file is the only Drive scope?" \
  || { warn "Fix that first, then re-run the wizard."; exit 1; }

stage "Google: OAuth client for iOS and macOS"
say "One iOS-type client serves iOS, iPadOS and macOS. It has no secret."
open_url "https://console.cloud.google.com/auth/clients/create"
step "Application type: iOS."
step "Name: LeafPDF Apple. Bundle ID: $BUNDLE_ID"
step "Create, then copy the Client ID (ends in .apps.googleusercontent.com)."
ask_valid GOOGLE_CLIENT_ID "Paste the Google client ID:" "$GOOGLE_ID_RE" \
  "That isn't <number>-<id>.apps.googleusercontent.com."
write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
# Google's redirect scheme for iOS-type clients is the reversed client ID.
write_env GOOGLE_REDIRECT_SCHEME "com.googleusercontent.apps.${GOOGLE_CLIENT_ID%.apps.googleusercontent.com}"
write_clients

stage "Microsoft: app registration (personal accounts only)"
say "Work and school accounts can't consent to Files.ReadWrite.AppFolder."
open_url "https://entra.microsoft.com/#view/Microsoft_AAD_RegisteredApps/CreateApplicationBlade/isMSAApp~/true"
step "Name: LeafPDF. It names the OneDrive folder: Apps/LeafPDF."
step "Supported account types: Personal Microsoft accounts only."
step "Redirect URI: platform 'Public client/native (mobile & desktop)', value"
say "    msauth.$BUNDLE_ID://auth"
step "Register."
note "No directory? Sign in with your personal account at https://portal.azure.com → App registrations."
pause "App registered?"

stage "Microsoft: permissions and public client"
open_url "$MS_APPS"
step "LeafPDF → API permissions → Add a permission → Microsoft Graph"
step "→ Delegated permissions → add Files.ReadWrite.AppFolder and offline_access."
note "User.Read is there by default; leave it. No admin consent needed."
step "Authentication → Settings → 'Allow public client flows' → Yes. Save."
pause "Permissions added and public client flows allowed?"

stage "Microsoft: client ID, then commit"
open_url "$MS_APPS"
step "LeafPDF → Overview → copy 'Application (client) ID'."
ask_valid MICROSOFT_CLIENT_ID "Paste the Microsoft client ID:" "$MICROSOFT_ID_RE" \
  "That isn't a GUID (xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx)."
write_env MICROSOFT_CLIENT_ID "$MICROSOFT_CLIENT_ID"
write_env MICROSOFT_REDIRECT_SCHEME "msauth.$BUNDLE_ID"
write_clients
printf '\n'
say "The IDs are public, not secrets. The Apple app reads them from Info.plist."
if git ls-files --error-unmatch "$CLIENTS_FILE" >/dev/null 2>&1 && git diff --quiet -- "$CLIENTS_FILE"; then
  say "Nothing changed since the last commit."
elif confirm "Commit $CLIENTS_FILE?"; then
  git add -- "$CLIENTS_FILE"
  git commit -m "Configure Google and Microsoft OAuth clients" -- "$CLIENTS_FILE" >/dev/null
  say "Committed. Run 'make apple-project' to regenerate the Xcode project."
else
  SKIPPED+=("commit $CLIENTS_FILE")
fi

finish
}

run_wizard "$@"; exit
